import sys

def min_roads_to_demolish(n, q):
    total_edges = n * (n - 1) // 2
    required_edges = total_edges - (q * (q - 1) // 2)
    return required_edges

def main():
    input_data = sys.stdin.read().splitlines()
    t = int(input_data[0])
    results = []
    for i in range(1, t + 1):
        n, q = map(int, input_data[i].split())
        results.append(min_roads_to_demolish(n, q))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
